function permiso() {
  return (sesion && PERMISOS[sesion.perfil]) || PERMISOS.reclamos;
}
function especialistas() {
  return USUARIOS.filter(
    (u) =>
      u.activo &&
      [
        "especialista",
        "coordinador",
        "reclamos",
        "operaciones",
        "suscripcion",
      ].includes(u.perfil),
  ).map((u) => u.nombre);
}

