function tab(t) {
  document
    .querySelectorAll(".tabpane")
    .forEach((p) => p.classList.add("hidden"));

  const pantalla = $("tab-" + t);
  if (pantalla) {
    pantalla.classList.remove("hidden");
  }

  const marcado =
    {
      detalle: "bandeja",
      "detalle-pa": "preauth",
      "detalle-prov": "provs",
    }[t] || t;

  document
    .querySelectorAll(".sidebar .item")
    .forEach((i) => i.classList.toggle("on", i.dataset.tab === marcado));

  if (t === "dash") {
    pintarDash();
  }
  if (t === "bandeja") {
    pintarBandeja();
  }
  if (t === "preauth") {
    pintarPA();
  }
  if (t === "provs") {
    pintarProvs();
  }
  if (t === "admin") {
    pintarAdmin();
  }
}

