function normProv(p) {
  const x = (p || "").toLowerCase();
  if (x.includes("bocas")) return "Bocas del Toro";
  if (x.includes("chiri") || x.includes("david")) return "Chiriquí";
  if (x.includes("coron")) return "Coclé";
  if (x.includes("coclé") || x.includes("cocle") || x.includes("penonom"))
    return "Coclé";
  if (x.includes("colon") || x.includes("colón")) return "Colón";
  if (x.includes("darién") || x.includes("darien")) return "Darién";
  if (x.includes("herre") || x.includes("chitr")) return "Herrera";
  if (x.includes("los santos") || x.includes("tablas")) return "Los Santos";
  if (x.includes("oeste") || x.includes("chorrera") || x.includes("chepo"))
    return "Panamá Oeste";
  if (x.includes("veraguas")) return "Veraguas";
  if (x.includes("panam")) return "Panamá";
  return p || "—";
}
RED.forEach((r) => {
  r.pN = normProv(r.p);
});
const RED_ESPECIALIDADES = [
  ...new Set(RED.map((r) => r.e).filter(Boolean)),
].sort();
const RED_PROVINCIAS = [...new Set(RED.map((r) => r.pN))].sort();

/* ================= CERTIFICACIÓN DE PRE-AUTORIZACIÓN (formato oficial Sagicor) ================= */
function generarCertPreauth(d) {
  // d = objeto con datos de la solicitud aprobada
  const hoy = new Date().toLocaleDateString("es-PA", {
    day: "numeric",
    month: "long",
    year: "numeric",
  });
  const w = window.open("", "_blank");
  const css = `
    body{font-family:'Public Sans',Arial,sans-serif;color:#122B3F;background:#fff;margin:0;padding:0}
    .cert{max-width:820px;margin:0 auto;padding:36px 44px}
    .cert-head{display:flex;justify-content:space-between;align-items:center;border-bottom:3px solid #00B6F0;padding-bottom:14px;margin-bottom:22px}
    .cert-head img{height:52px}
    .cert-head .marca{font-family:'Source Serif 4',Georgia,serif;color:#0E3A5D;font-size:20px;font-weight:700;letter-spacing:.5px}
    .cert-head .marca span{display:block;font-family:'IBM Plex Mono',monospace;font-size:10px;letter-spacing:2px;color:#5E9A22;text-transform:uppercase;margin-top:4px}
    h1{font-family:'Source Serif 4',Georgia,serif;color:#0E3A5D;font-size:19px;text-align:center;margin:12px 0 6px;text-transform:uppercase;letter-spacing:.5px}
    h2{font-family:'Source Serif 4',Georgia,serif;color:#0E3A5D;font-size:13.5px;text-align:center;font-weight:600;margin-bottom:20px;text-transform:uppercase;letter-spacing:1px}
    table.d{width:100%;border-collapse:collapse;margin-bottom:14px;font-size:12.5px}
    table.d td{border:1px solid #C7D6E0;padding:8px 10px;vertical-align:top}
    table.d td.lbl{background:#F2F7FA;color:#0E3A5D;font-weight:700;font-size:10.5px;text-transform:uppercase;letter-spacing:.4px;width:26%}
    .autoriz{background:linear-gradient(90deg,#0E3A5D,#0089B8);color:#fff;padding:10px 14px;font-weight:700;font-size:13px;letter-spacing:.6px;text-transform:uppercase;border-radius:4px;margin:16px 0 10px}
    .obs{background:#FFF9EE;border-left:4px solid #E8A13C;padding:10px 14px;font-size:12px;line-height:1.55;border-radius:4px;margin:12px 0}
    .firma{margin-top:36px;display:flex;justify-content:space-between;align-items:flex-end;gap:20px}
    .firma .box{flex:1;text-align:center}
    .firma .box .l{border-top:1.5px solid #0E3A5D;padding-top:6px;font-size:11px;color:#3E4750;font-weight:600;text-transform:uppercase;letter-spacing:.5px}
    .firma .box b{display:block;font-size:13px;color:#0E3A5D}
    .foot{margin-top:28px;padding-top:12px;border-top:1px solid #E3EDF3;font-size:10px;color:#76797D;text-align:center;line-height:1.6}
    .foot .reg{display:inline-flex;align-items:center;gap:8px;margin-top:6px;background:#F2F7FA;padding:6px 12px;border-radius:20px}
    .foot .reg img{height:22px}
    .print-btn{position:fixed;top:14px;right:14px;background:#00B6F0;color:#fff;border:none;padding:10px 18px;border-radius:999px;font-weight:700;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.15)}
    @media print{.print-btn{display:none}.cert{padding:20px 30px}body{background:#fff}}
  `;
  const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
    <title>Certificación PA · ${d.num || ""} · Sagicor Panamá</title>
    <link href="https://fonts.googleapis.com/css2?family=Source+Serif+4:wght@400;600;700&family=Public+Sans:wght@400;600;700&family=IBM+Plex+Mono:wght@500&display=swap" rel="stylesheet">
    <style>${css}</style></head><body>
    <button class="print-btn" onclick="window.print()">🖨️ Imprimir / PDF</button>
    <div class="cert">
      <div class="cert-head">
        <div class="marca">Sagicor Panamá<span>Compañía de Seguros</span></div>
        <div style="text-align:right;font-size:11px;color:#3E4750">
          <div><b>N° Certificación:</b> ${d.num || "—"}</div>
          <div>Emitido: ${hoy}</div>
        </div>
      </div>
      <h1>Certificación de Pre-Autorización para:</h1>
      <h2>Hospitalizaciones, Cirugías Electivas y Estudios Especiales</h2>
      <table class="d">
        <tr><td class="lbl">Fecha</td><td>${d.fecha || hoy}</td>
            <td class="lbl">Nombre del paciente</td><td>${d.paciente || ""}</td>
            <td class="lbl">Cédula</td><td>${d.cedulaPac || d.cedula || ""}</td></tr>
        <tr><td class="lbl">Nombre del asegurado</td><td>${d.asegurado || ""}</td>
            <td class="lbl">Colectivo</td><td>${d.colectivo || "—"}</td>
            <td class="lbl">N° de póliza</td><td>${d.poliza || "—"}</td></tr>
        <tr><td class="lbl">Sexo del paciente</td><td>${d.sexo || ""}</td>
            <td class="lbl">Relación con el asegurado</td><td>${d.parentesco || "Titular"}</td>
            <td class="lbl">Edad</td><td>${d.edad || ""}</td></tr>
      </table>
      <div class="autoriz">Autorización para</div>
      <table class="d">
        <tr><td class="lbl">Hospital / Clínica</td><td colspan="5">${d.hospital || ""}</td></tr>
        <tr><td class="lbl">Hospitalización</td><td>${d.hospitalizacion || "NO"}</td>
            <td class="lbl">Estadía promedio</td><td>${d.estadia || "—"}</td>
            <td class="lbl">Habitación</td><td>${d.habitacion || "—"}</td></tr>
        <tr><td class="lbl">Diagnóstico(s)</td><td colspan="5">${d.diagnostico || ""}</td></tr>
        <tr><td class="lbl">Procedimientos</td><td colspan="4">${d.procedimientos || ""}</td>
            <td class="lbl">CPT</td></tr>
        ${(d.cptRows || []).map((r) => `<tr><td></td><td colspan="4">${r.desc}</td><td>${r.cpt || ""}</td></tr>`).join("")}
      </table>
      ${d.observaciones ? `<div class="obs"><b>Observaciones / Procedimientos especiales:</b><br>${d.observaciones}</div>` : ""}
      <table class="d" style="margin-top:14px">
        <tr><td class="lbl">Lugar de atención</td><td>${d.hospital || ""}</td>
            <td class="lbl">Teléfono</td><td>${d.telHosp || "—"}</td></tr>
        <tr><td class="lbl">Médico responsable</td><td>${d.medico || ""}</td>
            <td class="lbl">Especialidad</td><td>${d.especialidad || "—"}</td></tr>
        <tr><td class="lbl">Aprobado por</td><td>${d.aprobadoPor || "Aileen Rodríguez · Sagicor Panamá"}</td>
            <td class="lbl">Certificación válida hasta</td><td>${d.validaHasta || ""}</td></tr>
      </table>
      <div class="firma">
        <div class="box"><b>Sagicor Panamá</b><div class="l">Firma y sello autorizado</div></div>
      </div>
      <div class="foot">
        Documento electrónico generado por el Portal de Autogestión de Sagicor Panamá.<br>
        Válido sin firma manuscrita conforme a la Ley 51 de 2008 sobre documentos y firmas electrónicas.<br>
        <div class="reg"><img src="data:image/png;base64," alt="SSRP">Regulada por la Superintendencia de Seguros y Reaseguros de Panamá</div>
      </div>
    </div></body></html>`;
  w.document.write(html);
  w.document.close();
}

/* ================= RED MÉDICA (portal interno) ================= */
function pintarRed() {
  const q = (document.getElementById("ir-q").value || "").toLowerCase().trim();
  const esp = document.getElementById("ir-esp").value;
  const prov = document.getElementById("ir-prov").value;
  let f = RED;
  if (esp) f = f.filter((r) => r.e === esp);
  if (prov) f = f.filter((r) => r.pN === prov);
  if (q)
    f = f.filter((r) =>
      (r.n + " " + r.d + " " + r.c + " " + r.e).toLowerCase().includes(q),
    );
  const tb = document.getElementById("ir-body");
  const limit = 500;
  tb.innerHTML =
    f
      .slice(0, limit)
      .map(
        (r) =>
          `<tr class="fila"><td style="color:var(--profundo);font-weight:600">${r.e || "—"}</td><td>${r.n || "—"}</td><td style="font-size:12px">${r.d || "—"}</td><td>${r.pN}</td><td>${r.c || "—"}</td><td class="mono">${r.t || "—"}</td></tr>`,
      )
      .join("") ||
    '<tr><td colspan="6" style="padding:20px;text-align:center;color:var(--pizarra)">Sin resultados.</td></tr>';
  document.getElementById("ir-count").textContent =
    `${Math.min(f.length, limit)} de ${f.length} resultados${f.length > limit ? " (afine su búsqueda)" : ""}.`;
}
function initRedInterno() {
  document.getElementById("red-total").textContent =
    RED.length.toLocaleString("es-PA");
  const se = document.getElementById("ir-esp"),
    sp = document.getElementById("ir-prov");
  se.insertAdjacentHTML(
    "beforeend",
    RED_ESPECIALIDADES.map((x) => `<option>${x}</option>`).join(""),
  );
  sp.insertAdjacentHTML(
    "beforeend",
    RED_PROVINCIAS.map((x) => `<option>${x}</option>`).join(""),
  );
  pintarRed();
}
function exportarRedCSV() {
  const rows = [
    ["Especialidad", "Nombre", "Direccion", "Provincia", "Ciudad", "Telefono"],
  ];
  RED.forEach((r) => rows.push([r.e, r.n, r.d, r.pN, r.c, r.t]));
  const csv = rows
    .map((r) =>
      r.map((v) => '"' + String(v || "").replace(/"/g, '""') + '"').join(","),
    )
    .join("\n");
  const b = new Blob([csv], { type: "text/csv;charset=utf-8;" });
  const u = URL.createObjectURL(b);
  const a = document.createElement("a");
  a.href = u;
  a.download = "red_medica_sagicor.csv";
  a.click();
  URL.revokeObjectURL(u);
  toast("CSV exportado");
}
// Hook para inicializar cuando se abre el tab
