function agregarBanner() {
  seqBanner++;
  BANNERS.push({
    id: seqBanner,
    nombre: "Nueva campaña",
    desde: HOY,
    hasta: HOY,
    url: "",
    activo: false,
    orden: BANNERS.length + 1,
  });
  audit("Banner creado", "—", "Nueva campaña");
  pintarBanners();
}
function toggleBanner(id) {
  const b = BANNERS.find((x) => x.id === id);
  b.activo = !b.activo;
  audit("Banner " + (b.activo ? "activado" : "desactivado"), "", b.nombre);
  pintarBanners();
}
function borrarBanner(id) {
  const i = BANNERS.findIndex((x) => x.id === id);
  if (i >= 0) {
    audit("Banner eliminado", BANNERS[i].nombre, "—");
    BANNERS.splice(i, 1);
    pintarBanners();
  }
}
function setBannerOrden(id, v) {
  const b = BANNERS.find((x) => x.id === id);
  b.orden = Number(v) || 1;
  pintarBanners();
}
function setBannerCampo(id, k, v) {
  const b = BANNERS.find((x) => x.id === id);
  audit("Banner: " + k, b[k], v);
  b[k] = v;
}

